			function cntSum(){
			    var dsList = app.lookup("dsList");
			    var stg2Sum = 0;
			    var stg3Sum = 0;
			    var stg4Sum = 0;
			    var stg5Sum = 0;
			    //ValueUtil.fixNumber(
			    for(var i = 0; i < dsList.getRowCount(); i++){
			        stg2Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG2_FNSH_CNT"));
			        stg2Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG2_FAILR_CNT"));
			        stg3Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG3_FNSH_CNT"));
			        stg3Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG3_FAILR_CNT"));
			        stg4Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG4_FNSH_CNT"));
			        stg4Sum += ValueUtil.fixNumber(dsList.getValue(i, "STG4_FAILR_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "FOUND_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "JOB_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "JOB_CNT1"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "NEIL_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "PACKAGE_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "NTN_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "PRVATE_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "UNIVA_CNT"));
			        stg5Sum += ValueUtil.fixNumber(dsList.getValue(i, "CERTI_CNT"));
			        dsList.setValue(i, "STG2_SUM", stg2Sum);
			        dsList.setValue(i, "STG3_SUM", stg3Sum);
			        dsList.setValue(i, "STG4_SUM", stg4Sum);
			        dsList.setValue(i, "STG5_SUM", stg5Sum);
			        stg2Sum = 0;
			        stg3Sum = 0;
			        stg4Sum = 0;
			        stg5Sum = 0;
			    }
			    util.Control.redraw(app, "grdList");
			};
